    89	#ifdef CONFIG_BOOTLOADER_WDT_ENABLE
    90	    // After changing a frequency WDT timeout needs to be set for new frequency.
    91	    stage_timeout_ticks = (uint32_t)((uint64_t)CONFIG_BOOTLOADER_WDT_TIME_MS * rtc_clk_slow_freq_get_hz() / 1000);
    92	    wdt_hal_write_protect_disable(&rtc_wdt_ctx);
    93	    wdt_hal_feed(&rtc_wdt_ctx);
    94	    wdt_hal_config_stage(&rtc_wdt_ctx, WDT_STAGE0, stage_timeout_ticks, WDT_STAGE_ACTION_RESET_RTC);
    95	    wdt_hal_write_protect_enable(&rtc_wdt_ctx);
    96	#endif
    97	
    98	    rtc_cpu_freq_config_t old_config, new_config;
    99	    rtc_clk_cpu_freq_get_config(&old_config);
   100	    const uint32_t old_freq_mhz = old_config.freq_mhz;
   101	    const uint32_t new_freq_mhz = CONFIG_ESP_DEFAULT_CPU_FREQ_MHZ;
   102	
   103	    bool res = rtc_clk_cpu_freq_mhz_to_config(new_freq_mhz, &new_config);
   104	    assert(res);
