   106	    // Wait for UART TX to finish, otherwise some UART output will be lost
   107	    // when switching APB frequency
   108	    if (CONFIG_ESP_CONSOLE_ROM_SERIAL_PORT_NUM != -1) {
   109	        esp_rom_output_tx_wait_idle(CONFIG_ESP_CONSOLE_ROM_SERIAL_PORT_NUM);
   110	    }
   111	
   112	    if (res)  {
   113	        rtc_clk_cpu_freq_set_config(&new_config);
   114	    }
   115	
   116	    // Re calculate the ccount to make time calculation correct.
   117	    esp_cpu_set_cycle_count((uint64_t)esp_cpu_get_cycle_count() * new_freq_mhz / old_freq_mhz);
