    31	void rtc_clk_init(rtc_clk_config_t cfg)
    32	{
    33	    rtc_cpu_freq_config_t old_config, new_config;
    34	
    35	    /* Set tuning parameters for RC_FAST, RC_SLOW, and RC32K clocks.
    36	     * Note: this doesn't attempt to set the clocks to precise frequencies.
    37	     * Instead, we calibrate these clocks against XTAL frequency later, when necessary.
    38	     * - SCK_DCAP value controls tuning of RC_SLOW clock.
    39	     *   The higher the value of DCAP is, the lower is the frequency.
    40	     * - CK8M_DFREQ value controls tuning of RC_FAST clock.
    41	     *   CLK_8M_DFREQ constant gives the best temperature characteristics.
    42	     * - RC32K_DFREQ value controls tuning of RC32K clock.
    43	     */
    44	    REG_SET_FIELD(LP_CLKRST_FOSC_CNTL_REG, LP_CLKRST_FOSC_DFREQ, cfg.clk_8m_dfreq);
    45	    REGI2C_WRITE_MASK(I2C_DIG_REG, I2C_DIG_REG_SCK_DCAP, cfg.slow_clk_dcap);
    46	    REG_SET_FIELD(LP_CLKRST_RC32K_CNTL_REG, LP_CLKRST_RC32K_DFREQ, cfg.rc32k_dfreq);
    47	
    48	    REGI2C_WRITE_MASK(I2C_DIG_REG, I2C_DIG_REG_FORCE_RTC_DREG, 1);
    49	    REGI2C_WRITE_MASK(I2C_DIG_REG, I2C_DIG_REG_FORCE_DIG_DREG, 1);
    50	    REGI2C_WRITE_MASK(I2C_DIG_REG, I2C_DIG_REG_XPD_RTC_REG, 0);
    51	    REGI2C_WRITE_MASK(I2C_DIG_REG, I2C_DIG_REG_XPD_DIG_REG, 0);
    52	
    53	    REGI2C_WRITE_MASK(I2C_BIAS, I2C_BIAS_OR_FORCE_XPD_CK, 0);
    54	    REGI2C_WRITE_MASK(I2C_BIAS, I2C_BIAS_OR_FORCE_XPD_REF_OUT_BUF, 0);
    55	    REGI2C_WRITE_MASK(I2C_BIAS, I2C_BIAS_OR_FORCE_XPD_IPH, 0);
    56	    REGI2C_WRITE_MASK(I2C_BIAS, I2C_BIAS_OR_FORCE_XPD_VGATE_BUF, 0);
    57	
    58	    uint32_t hp_dbias = get_act_hp_dbias();
    59	    uint32_t lp_dbias = get_act_lp_dbias();
    60	    pmu_ll_hp_set_regulator_xpd(&PMU, PMU_MODE_HP_ACTIVE, true);
    61	    pmu_ll_hp_set_regulator_dbias(&PMU, PMU_MODE_HP_ACTIVE, hp_dbias);
    62	    pmu_ll_lp_set_regulator_dbias(&PMU, PMU_MODE_LP_ACTIVE, lp_dbias);
    63	
    64	    uint32_t pvt_hp_dcmvset = GET_PERI_REG_BITS2(PMU_HP_ACTIVE_HP_REGULATOR0_REG, PMU_HP_DBIAS_VOL_V, PMU_HP_DBIAS_VOL_S);
    65	    uint32_t hp_dcmvset =  HP_CALI_ACTIVE_DCM_VSET_DEFAULT;
    66	    if (pvt_hp_dcmvset > hp_dcmvset) {
    67	        hp_dcmvset = pvt_hp_dcmvset;
    68	    }
    69	    // Switch to DCDC
    70	#if CONFIG_ESP32P4_REV_MIN_FULL >= 300
    71	    unsigned chip_version = efuse_hal_chip_revision();
    72	    if (ESP_CHIP_REV_ABOVE(chip_version, 301)) {
    73	        SET_PERI_REG_MASK(PMU_DCM_CTRL_REG, PMU_DCDC_FB_RES_FORCE_PD);
    74	    }
    75	#endif
    76	    pmu_ll_set_dcdc_en(&PMU, true);
    77	    pmu_ll_set_dcdc_switch_force_power_down(&PMU, false);
    78	    pmu_ll_hp_set_dcm_vset(&PMU, PMU_MODE_HP_ACTIVE, hp_dcmvset);
    79	    SET_PERI_REG_MASK(PMU_HP_ACTIVE_HP_REGULATOR0_REG, PMU_DIG_REGULATOR0_DBIAS_SEL); // Hand over control of dbias to pmu
    80	    esp_rom_delay_us(1000);
    81	#if CONFIG_ESP32P4_REV_MIN_FULL >= 300
    82	    if (ESP_CHIP_REV_ABOVE(chip_version, 301)) {
    83	        REG_SET_FIELD(LP_SYSTEM_REG_SYS_CTRL_REG, LP_SYSTEM_REG_LP_FIB_SEL, 0xEF);// lp_fib_sel bit4 set to 0: select dig_fib_reg instead of ana_fib_reg
    84	        CLEAR_PERI_REG_MASK(PMU_DCM_CTRL_REG, PMU_DCDC_FB_RES_FORCE_PD);
    85	        esp_rom_delay_us(10);
    86	    }
    87	#endif
    88	    pmu_ll_hp_set_regulator_xpd(&PMU, PMU_MODE_HP_ACTIVE, false);
    89	
    90	    soc_xtal_freq_t xtal_freq = cfg.xtal_freq;
    91	    esp_rom_output_tx_wait_idle(0);
    92	    rtc_clk_xtal_freq_update(xtal_freq);
    93	
    94	    /* Set CPU frequency */
    95	    rtc_clk_cpu_freq_get_config(&old_config);
    96	    uint32_t freq_before = old_config.freq_mhz;
    97	    bool res = rtc_clk_cpu_freq_mhz_to_config(cfg.cpu_freq_mhz, &new_config);
    98	    if (!res) {
    99	        ESP_HW_LOGE(TAG, "invalid CPU frequency value");
   100	        abort();
   101	    }
   102	    rtc_clk_cpu_freq_set_config(&new_config);
   103	
   104	    /* Re-calculate the ccount to make time calculation correct. */
   105	    esp_cpu_set_cycle_count( (uint64_t)esp_cpu_get_cycle_count() * cfg.cpu_freq_mhz / freq_before );
   106	
   107	    /* Slow & fast clocks setup */
   108	    // We will not power off RC_FAST in bootloader stage even if it is not being used as any
   109	    // cpu / rtc_fast / rtc_slow clock sources, this is because RNG always needs it in the bootloader stage.
   110	    bool need_rc_fast_en = true;
   111	    if (cfg.slow_clk_src == SOC_RTC_SLOW_CLK_SRC_XTAL32K) {
   112	        rtc_clk_32k_enable(true);
   113	    } else if (cfg.slow_clk_src == SOC_RTC_SLOW_CLK_SRC_RC32K) {
   114	       rtc_clk_rc32k_enable(true);
   115	    }
   116	    rtc_clk_8m_enable(need_rc_fast_en);
   117	    rtc_clk_fast_src_set(cfg.fast_clk_src);
   118	    rtc_clk_slow_src_set(cfg.slow_clk_src);
   119	}
