/****************************************************************************
 * Name: systimer_irq_handler
 *
 * Description:
 *   Handler to be executed by the Systimer ISR.
 *
 * Input Parameters:
 *   irq           - IRQ associated to that interrupt.
 *   context       - Interrupt register state save info.
 *   arg           - A pointer to the argument provided when the interrupt
 *                   was registered.
 *
 * Returned Value:
 *   Zero on success; a negated errno value on failure.
 *
 ****************************************************************************/

static int systimer_irq_handler(int irq, void *context, void *arg)
{
  static bool traced;
  bool trace = !traced;

  if (trace)
    {
      traced = true;
      up_putc('X');
    }

  systimer_ll_clear_alarm_int(systimer_hal.dev,
                              SYSTIMER_ALARM_OS_TICK_CORE0);

#ifdef CONFIG_ARCH_CHIP_ESP32P4
  /* Wait until the level interrupt is deasserted before returning through
   * the CLIC.  Otherwise the same interrupt can be taken again immediately.
   */

  while (systimer_ll_is_alarm_int_fired(systimer_hal.dev,
                                        SYSTIMER_ALARM_OS_TICK_CORE0))
    {
    }
#endif

  if (trace)
    {
      up_putc('Y');
    }

  /* Process timer interrupt */

  nxsched_process_timer();

  if (trace)
    {
      up_putc('Z');
    }

  return OK;
}

