   885	//Muxing an interrupt source to interrupt 6, 7, 11, 15, 16 or 29 cause the interrupt to effectively be disabled.
   886	#define INT_MUX_DISABLED_INTNO 6
   887	
   888	esp_err_t ESP_INTR_IRAM_ATTR esp_intr_enable(intr_handle_t handle)
   889	{
   890	    if (!handle) {
   891	        return ESP_ERR_INVALID_ARG;
   892	    }
   893	    esp_os_enter_critical_safe(&spinlock);
   894	    int source;
   895	    if (handle->shared_vector_desc) {
   896	        handle->shared_vector_desc->disabled = 0;
   897	        source=handle->shared_vector_desc->source;
   898	    } else {
   899	        source=handle->vector_desc->source;
   900	    }
   901	    if (source >= 0) {
   902	        //Disabled using int matrix; re-connect to enable
